class Solution {
  public int[] runningSum(int[] nums) {
    for (int i = 1; i < nums.length; i++) {
      nums[i] += nums[i - 1];
    }
    return nums;
  }
}

class Solution {
  public int pivotIndex(int[] nums) {
    int total = 0;
    for (int num : nums) {
      total += num;
    }

    int left = 0;
    for (int i = 0; i < nums.length; i++) {
      int right = total - left - nums[i];
      if (left == right) return i;
      left += nums[i];
    }
    return -1;
  }
}

class Solution {
  public int largestAltitude(int[] gain) {
    int altitude = 0;
    int highest = 0;
    for (int change : gain) {
      altitude += change;
      highest = Math.max(highest, altitude);
    }
    return highest;
  }
}

class Solution {
  public int minStartValue(int[] nums) {
    int prefix = 0;
    int minPrefix = 0;
    for (int num : nums) {
      prefix += num;
      minPrefix = Math.min(minPrefix, prefix);
    }
    return 1 - minPrefix;
  }
}

class NumArray {
  private final int[] prefix;

  public NumArray(int[] nums) {
    prefix = new int[nums.length + 1];
    for (int i = 0; i < nums.length; i++) {
      prefix[i + 1] = prefix[i] + nums[i];
    }
  }

  public int sumRange(int left, int right) {
    return prefix[right + 1] - prefix[left];
  }
}

class NumMatrix {
  private final int[][] prefix;

  public NumMatrix(int[][] matrix) {
    int rows = matrix.length;
    int cols = matrix[0].length;
    prefix = new int[rows + 1][cols + 1];
    for (int row = 0; row < rows; row++) {
      for (int col = 0; col < cols; col++) {
        prefix[row + 1][col + 1] = matrix[row][col]
            + prefix[row][col + 1]
            + prefix[row + 1][col]
            - prefix[row][col];
      }
    }
  }

  public int sumRegion(int row1, int col1, int row2, int col2) {
    return prefix[row2 + 1][col2 + 1]
        - prefix[row1][col2 + 1]
        - prefix[row2 + 1][col1]
        + prefix[row1][col1];
  }
}

class Solution {
  public int[][] matrixBlockSum(int[][] mat, int k) {
    int rows = mat.length;
    int cols = mat[0].length;
    int[][] prefix = new int[rows + 1][cols + 1];

    for (int row = 0; row < rows; row++) {
      for (int col = 0; col < cols; col++) {
        prefix[row + 1][col + 1] = mat[row][col]
            + prefix[row][col + 1]
            + prefix[row + 1][col]
            - prefix[row][col];
      }
    }

    int[][] ans = new int[rows][cols];
    for (int row = 0; row < rows; row++) {
      for (int col = 0; col < cols; col++) {
        int r1 = Math.max(0, row - k);
        int c1 = Math.max(0, col - k);
        int r2 = Math.min(rows - 1, row + k);
        int c2 = Math.min(cols - 1, col + k);
        ans[row][col] = sum(prefix, r1, c1, r2, c2);
      }
    }
    return ans;
  }

  private int sum(int[][] prefix, int r1, int c1, int r2, int c2) {
    return prefix[r2 + 1][c2 + 1]
        - prefix[r1][c2 + 1]
        - prefix[r2 + 1][c1]
        + prefix[r1][c1];
  }
}

class Solution {
  public int[] leftRightDifference(int[] nums) {
    int total = 0;
    for (int num : nums) total += num;

    int[] ans = new int[nums.length];
    int left = 0;
    for (int i = 0; i < nums.length; i++) {
      int right = total - left - nums[i];
      ans[i] = Math.abs(left - right);
      left += nums[i];
    }
    return ans;
  }
}

