class Solution {
  public int maxSubArrayLen(int[] nums, int k) {
    Map<Integer, Integer> firstIndex = new HashMap<>();
    firstIndex.put(0, -1);

    int prefix = 0;
    int best = 0;
    for (int i = 0; i < nums.length; i++) {
      prefix += nums[i];
      if (firstIndex.containsKey(prefix - k)) {
        best = Math.max(best, i - firstIndex.get(prefix - k));
      }
      firstIndex.putIfAbsent(prefix, i);
    }
    return best;
  }
}

class Solution {
  public int[] corpFlightBookings(int[][] bookings, int n) {
    int[] diff = new int[n + 1];
    for (int[] booking : bookings) {
      int start = booking[0] - 1;
      int end = booking[1];
      int seats = booking[2];
      diff[start] += seats;
      diff[end] -= seats;
    }

    int running = 0;
    int[] ans = new int[n];
    for (int i = 0; i < n; i++) {
      running += diff[i];
      ans[i] = running;
    }
    return ans;
  }
}

class Solution {
  public boolean carPooling(int[][] trips, int capacity) {
    int[] diff = new int[1002];
    for (int[] trip : trips) {
      diff[trip[1]] += trip[0];
      diff[trip[2]] -= trip[0];
    }

    int passengers = 0;
    for (int location = 0; location <= 1000; location++) {
      passengers += diff[location];
      if (passengers > capacity) return false;
    }
    return true;
  }
}

class Solution {
  public String shiftingLetters(String s, int[][] shifts) {
    int n = s.length();
    int[] diff = new int[n + 1];
    for (int[] shift : shifts) {
      int delta = shift[2] == 1 ? 1 : -1;
      diff[shift[0]] += delta;
      diff[shift[1] + 1] -= delta;
    }

    char[] ans = s.toCharArray();
    int running = 0;
    for (int i = 0; i < n; i++) {
      running += diff[i];
      int offset = ((ans[i] - 'a' + running) % 26 + 26) % 26;
      ans[i] = (char) ('a' + offset);
    }
    return new String(ans);
  }
}
